// Some portions generated by Claude
package org.eclipse.rdf4j.workbench.commands;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.repository.manager.RepositoryInfo;
import org.eclipse.rdf4j.repository.manager.RepositoryManager;
import org.eclipse.rdf4j.workbench.base.TransformationServlet;
import org.eclipse.rdf4j.workbench.support.TestServletConfig;
import org.eclipse.rdf4j.workbench.util.WorkbenchPageProtocol;
import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;

import tools.jackson.databind.JsonNode;
import tools.jackson.databind.ObjectMapper;

/**
 * The repositories to delete, and the members to federate, are offered in ID order, as the Repositories list and the
 * repository switcher show them, not in the order the server happens to list them.
 */
class RepositoryChoiceOrderTest {

	private static final ObjectMapper JSON_MAPPER = new ObjectMapper();

	@Test
	void theDeletePageOffersRepositoriesInIdOrder() throws Exception {
		MockHttpServletResponse response = run(new DeleteServlet(), "delete",
				new MockHttpServletRequest("GET", "/delete"));

		assertThat(ids(response)).containsExactly("demo-lmdb", "demo-memory", "E2E", "verify");
	}

	@Test
	void theFederationFormOffersMembersInIdOrder() throws Exception {
		MockHttpServletRequest request = new MockHttpServletRequest("GET", "/create");
		request.addParameter("type", "federate");

		MockHttpServletResponse response = run(new CreateServlet(), "create", request);

		assertThat(ids(response)).containsExactly("demo-lmdb", "demo-memory", "E2E", "verify");
	}

	private static MockHttpServletResponse run(TransformationServlet servlet, String name,
			MockHttpServletRequest request) throws Exception {
		RepositoryManager manager = mock(RepositoryManager.class);
		// The order a server lists them in: by hash, not by ID.
		when(manager.getAllRepositoryInfos()).thenReturn(List.of(info("demo-lmdb"), info("verify"), info("E2E"),
				info("demo-memory")));
		servlet.setRepositoryManager(manager);
		servlet.init(TestServletConfig.withParams(name, "cookie-max-age", "300"));
		request.addHeader("Accept", WorkbenchPageProtocol.ACCEPT);
		try {
			MockHttpServletResponse response = new MockHttpServletResponse();
			servlet.service(request, response);
			return response;
		} finally {
			servlet.destroy();
		}
	}

	private static RepositoryInfo info(String id) {
		RepositoryInfo info = new RepositoryInfo();
		info.setId(id);
		info.setDescription(id + " store");
		info.setReadable(true);
		info.setWritable(true);
		return info;
	}

	/** The id column of the answer's rows, in order. */
	private static List<String> ids(MockHttpServletResponse response) throws Exception {
		List<JsonNode> records = response.getContentAsString()
				.lines()
				.filter(line -> !line.isBlank())
				.map(JSON_MAPPER::readTree)
				.toList();
		List<String> vars = new ArrayList<>();
		records.stream()
				.filter(record -> "vars".equals(record.path("type").asText()))
				.forEach(record -> record.path("values").forEach(value -> vars.add(value.asText())));
		int column = vars.indexOf("id");
		assertThat(column).as("id column in %s", vars).isGreaterThanOrEqualTo(0);
		List<String> ids = new ArrayList<>();
		records.stream()
				.filter(record -> "rows".equals(record.path("type").asText()))
				.forEach(record -> record.path("values")
						.forEach(row -> ids.add(row.get(column).path("value").asText())));
		return ids;
	}
}
